import {
  SchemaDocument,
  TypeDefinition,
  TypeNode,
  FieldDefinition,
} from '../ir/types';

/**
 * Generates Rust structs and enums with Serde serialization support.
 */
export function generateRust(doc: SchemaDocument): string {
  const lines: string[] = [
    '// Auto-generated by TypeBridge. DO NOT EDIT DIRECTLY.',
    'use serde::{Deserialize, Serialize};',
    'use std::collections::HashMap;',
    'use chrono::{DateTime, Utc};',
    'use uuid::Uuid;',
    '',
  ];

  for (const def of doc.definitions) {
    if (def.kind === 'struct') {
      lines.push(generateRustStruct(def));
      lines.push('');
    } else if (def.kind === 'enum') {
      lines.push(generateRustEnum(def));
      lines.push('');
    } else if (def.kind === 'alias') {
      lines.push(`pub type ${def.name} = ${mapTypeToRust(def.targetType)};`);
      lines.push('');
    }
  }

  return lines.join('\n');
}

function generateRustStruct(def: Extract<TypeDefinition, { kind: 'struct' }>): string {
  const lines: string[] = [];
  if (def.description) {
    lines.push(`/// ${def.description}`);
  }
  lines.push('#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]');
  lines.push(`pub struct ${def.name} {`);

  for (const field of def.fields) {
    const rustName = toSnakeCase(field.name);
    const rustType = mapTypeToRust(field.type);
    const isAliased = rustName !== field.name;

    if (field.description) {
      lines.push(`    /// ${field.description}`);
    }

    if (isAliased) {
      lines.push(`    #[serde(rename = "${field.name}")]`);
    }

    if (field.optional) {
      lines.push(`    #[serde(skip_serializing_if = "Option::is_none")]`);
      lines.push(`    pub ${rustName}: Option<${rustType}>,`);
    } else {
      lines.push(`    pub ${rustName}: ${rustType},`);
    }
  }

  lines.push('}');
  return lines.join('\n');
}

function generateRustEnum(def: Extract<TypeDefinition, { kind: 'enum' }>): string {
  const lines: string[] = [];
  if (def.description) {
    lines.push(`/// ${def.description}`);
  }
  lines.push('#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]');
  lines.push(`pub enum ${def.name} {`);

  for (const val of def.values) {
    const variantName = toPascalCase(val.name);
    const originalVal = String(val.value);
    if (variantName !== originalVal) {
      lines.push(`    #[serde(rename = "${originalVal}")]`);
    }
    lines.push(`    ${variantName},`);
  }

  lines.push('}');
  return lines.join('\n');
}

function mapTypeToRust(node: TypeNode): string {
  switch (node.kind) {
    case 'primitive':
      switch (node.primitive) {
        case 'string':
          return 'String';
        case 'number':
          return 'f64';
        case 'integer':
          return 'i64';
        case 'boolean':
          return 'bool';
        case 'date':
          return 'DateTime<Utc>';
        case 'uuid':
          return 'Uuid';
        case 'null':
          return '()';
        case 'any':
        default:
          return 'serde_json::Value';
      }
    case 'reference':
      return node.name;
    case 'array':
      return `Vec<${mapTypeToRust(node.elementType)}>`;
    case 'map':
      return `HashMap<${mapTypeToRust(node.keyType)}, ${mapTypeToRust(node.valueType)}>`;
    case 'optional':
      return `Option<${mapTypeToRust(node.innerType)}>`;
    case 'union':
      return 'serde_json::Value';
    case 'literal':
      return 'String';
    default:
      return 'serde_json::Value';
  }
}

function toSnakeCase(str: string): string {
  return str
    .replace(/([A-Z])/g, '_$1')
    .toLowerCase()
    .replace(/^_/, '');
}

function toPascalCase(str: string): string {
  return str
    .toLowerCase()
    .replace(/(?:^|_|[- ])(\w)/g, (_, c) => c.toUpperCase());
}
